from collections import Counter
def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for row in inp for x in row); bg=cnt.most_common(1)[0][0]
    # object = non-bg cells
    obj=[[inp[r][c]!=bg for r in range(H) for c in range(W)]
         for r in range(H) for c in range(W)]
    comps=[]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if obj[r*W+c] and not seen[r][c]:
                st=[(r,c)]; cells=[]
                seen[r][c]=True
                while st:
                    rr,cc=st.pop(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and obj[nr*W+nc] and not seen[nr][nc]:
                            seen[nr][nc]=True; st.append((nr,nc))
                comps.append(cells)
    comp=max(comps,key=len)
    rs=[r for r,c in comp]; cs=[c for r,c in comp]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    h=w=r1-r0+1=c1-c0+1
    stamp=[[None]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            stamp[i][j]=inp[r0+i][c0+j]
    out=[row[:] for row in inp]
    for r in range(H):
        for c in range(W):
            if inp[r][c]==3 and (r,c) not in comp:
                pr=r-h//2; pc=c-w//2
                for i in range(h):
                    for j in range(w):
                        rr,cc=pr+i,pc+j
                        if 0<=rr<H and 0<=cc<W:
                            out[rr][cc]=stamp[i][j]
    return out
